import json, re
samples = [
 {"q": "에어컨 22도로 맞춰줘", "a": '{"action":"set_ac","temp":22}'},
 {"q": "에어컨 22도로 맞춰 줘", "a": '{"action":"set_ac","temp":22}'},
 {"q": "창문 좀 열어", "a": '{"action":"open_window","seat":"driver"'},
 {"q": "히터 40도", "a": '{"action":"set_ac","temp":40}'},
 {"q": "근처 주유소 찾아줘", "a": '{"action":"search_poi","category":"gas"}'},
]
def ok(s):
    try:
        a = json.loads(s["a"])
    except json.JSONDecodeError:
        return "json"
    if a.get("action") == "set_ac" and not 16 <= a["temp"] <= 30:
        return "range"
    return None
def norm(t):
    return re.sub(r"\s+", "", t)
seen, kept, why = set(), [], {}
for s in samples:
    r = ok(s)
    if r:
        why[r] = why.get(r, 0) + 1
        continue
    k = norm(s["q"])
    if k in seen:
        why["dup"] = why.get("dup", 0) + 1
        continue
    seen.add(k)
    kept.append(s)
print(len(kept), why)
# 출력: 2 {'dup': 1, 'json': 1, 'range': 1}
